import functools

@functools.lru_cache(None)
def solve(segments, turn):
    # segments: sorted tuple of lengths of empty segments
    # turn: 0 for Alice (maximize U), 1 for Bob (minimize U)

    # Check if any move is possible
    possible_moves = []
    for i, length in enumerate(segments):
        if length >= 2:
            for pos in range(length - 1):
                # A tile covers pos and pos+1 (0-indexed)
                # This splits the segment of length 'length' into 
                # a segment of length 'pos' and a segment of length 'length - pos - 2'
                new_segments = list(segments)
                new_segments.pop(i)
                if pos > 0:
                    new_segments.append(pos)
                if length - pos - 2 > 0:
                    new_segments.append(length - pos - 2)
                possible_moves.append(tuple(sorted(new_segments)))

    if not possible_moves:
        # Game ends, calculate total uncovered squares
        return sum(segments)

    if turn == 0: # Alice's turn to maximize
        return max(solve(move, 1) for move in possible_moves)
    else: # Bob's turn to minimize
        return min(solve(move, 0) for move in possible_moves)

for n in range(1, 21):
    print(f"N={n}, U={solve((n,), 0)}")

