import itertools

def get_all_moves(board):
    moves = []
    for i in range(len(board) - 1):
        if board[i] == 0 and board[i+1] == 0:
            moves.append(i)
    return moves

def simulate(board, turn):
    # turn 0: Alice (max), turn 1: Bob (min)
    moves = get_all_moves(board)
    if not moves:
        return sum(1 for x in board if x == 0)

    if turn == 0:
        best_u = -1
        for m in moves:
            new_board = list(board)
            new_board[m] = 1
            new_board[m+1] = 1
            u = simulate(tuple(new_board), 1)
            if u > best_u:
                best_u = u
        return best_u
    else:
        best_u = float('inf')
        for m in moves:
            new_board = list(board)
            new_board[m] = 1
            new_board[m+1] = 1
            u = simulate(tuple(new_board), 0)
            if u < best_u:
                best_u = u
        return best_u

