import functools

def solve_with_move(segments, turn):
    possible_moves = []
    for i, length in enumerate(segments):
        if length >= 2:
            for pos in range(length - 1):
                new_segments = list(segments)
                new_segments.pop(i)
                if pos > 0:
                    new_segments.append(pos)
                if length - pos - 2 > 0:
                    new_segments.append(length - pos - 2)
                possible_moves.append((pos, i, tuple(sorted(new_segments))))

    if not possible_moves:
        return sum(segments), []

    if turn == 0:
        best_u = -1
        best_move_seq = []
        for pos, i, move in possible_moves:
            u, seq = solve_with_move(move, 1)
            if u > best_u:
                best_u = u
                best_move_seq = [(pos, i)] + seq
        return best_u, best_move_seq
    else:
        best_u = float('inf')
        best_move_seq = []
        for pos, i, move in possible_moves:
            u, seq = solve_with_move(move, 0)
            if u < best_u:
                best_u = u
                best_move_seq = [(pos, i)] + seq
        return best_u, best_move_seq

